begin;
create table if not exists public.hq_marketing_campaigns (id uuid primary key default gen_random_uuid(),name text not null,channel text not null,status text not null default 'draft',audience text,starts_at timestamptz,ends_at timestamptz,budget numeric,currency text default 'KES',notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status in ('draft','scheduled','active','paused','completed','archived')));
create table if not exists public.hq_marketing_events (id bigint generated always as identity primary key,campaign_id uuid references public.hq_marketing_campaigns(id) on delete set null,profile_id uuid references public.profiles(id) on delete set null,event_type text not null,source text,occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
create index if not exists hq_marketing_events_campaign_idx on public.hq_marketing_events(campaign_id,occurred_at desc); create index if not exists hq_marketing_events_profile_idx on public.hq_marketing_events(profile_id,occurred_at desc);
create table if not exists public.hq_user_status_events (id bigint generated always as identity primary key,profile_id uuid not null references public.profiles(id) on delete cascade,from_status text,to_status text not null,reason text,changed_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists hq_user_status_events_profile_idx on public.hq_user_status_events(profile_id,created_at desc);
alter table public.hq_marketing_campaigns enable row level security; alter table public.hq_marketing_events enable row level security; alter table public.hq_user_status_events enable row level security;
create policy hq_marketing_campaigns_owner_only on public.hq_marketing_campaigns for all to authenticated using(coalesce(public.is_platform_owner(),false)) with check(coalesce(public.is_platform_owner(),false));
create policy hq_marketing_events_owner_only on public.hq_marketing_events for all to authenticated using(coalesce(public.is_platform_owner(),false)) with check(coalesce(public.is_platform_owner(),false));
create policy hq_user_status_events_owner_only on public.hq_user_status_events for all to authenticated using(coalesce(public.is_platform_owner(),false)) with check(coalesce(public.is_platform_owner(),false));
create or replace function public.hq_user_directory(p_search text default null,p_role text default null,p_status text default null,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$ begin if auth.uid() is null or not coalesce(public.is_platform_owner(),false) then raise exception 'owner_authorization_required'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select p.id,p.full_name,p.role,p.account_status::text account_status,p.is_anonymized,p.created_at,p.updated_at,p.school_id,p.vc_id,p.arrived_at,(select max(e.created_at) from public.security_audit_events e where e.actor_id=p.id) last_security_activity,(select max(h.created_at) from public.hq_user_status_events h where h.profile_id=p.id) last_status_change,(select count(*) from public.billing_subscriptions bs where bs.profile_id=p.id and bs.status in ('active','trialing','past_due')) active_subscription_count from public.profiles p where (p_search is null or p.full_name ilike '%'||p_search||'%' or p.vc_id ilike '%'||p_search||'%') and (p_role is null or p.role=p_role) and (p_status is null or p.account_status::text=p_status) limit greatest(1,least(coalesce(p_limit,100),500))) x),'[]'::jsonb); end; $$;
revoke all on function public.hq_user_directory(text,text,text,integer) from public,anon; grant execute on function public.hq_user_directory(text,text,text,integer) to authenticated;
create or replace function public.hq_billing_overview(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$ begin if auth.uid() is null or not coalesce(public.is_platform_owner(),false) then raise exception 'owner_authorization_required'; end if; return jsonb_build_object('summary',jsonb_build_object('active',(select count(*) from public.billing_subscriptions where status='active'),'trialing',(select count(*) from public.billing_subscriptions where status='trialing'),'past_due',(select count(*) from public.billing_subscriptions where status='past_due'),'cancelled',(select count(*) from public.billing_subscriptions where status='cancelled'),'revenue_30d',(select coalesce(sum(amount),0) from public.billing_subscription_events where occurred_at>=now()-interval '30 days' and event_type in ('payment_succeeded','subscription_started','renewal'))),'subscriptions',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select b.id,b.profile_id,p.full_name,p.role,b.plan_key,b.status,b.currency,b.amount,b.billing_interval,b.current_period_end,b.source,b.created_at from public.billing_subscriptions b left join public.profiles p on p.id=b.profile_id order by b.created_at desc limit greatest(1,least(coalesce(p_limit,100),500))) x),'[]'::jsonb)); end; $$;
revoke all on function public.hq_billing_overview(integer) from public,anon; grant execute on function public.hq_billing_overview(integer) to authenticated;
create or replace function public.hq_marketing_overview() returns jsonb language plpgsql security definer set search_path=public,extensions,pg_temp as $$ begin if auth.uid() is null or not coalesce(public.is_platform_owner(),false) then raise exception 'owner_authorization_required'; end if; return jsonb_build_object('campaigns',(select count(*) from public.hq_marketing_campaigns where status not in ('archived','completed')),'active_campaigns',(select count(*) from public.hq_marketing_campaigns where status='active'),'events_30d',(select count(*) from public.hq_marketing_events where occurred_at>=now()-interval '30 days'),'leads_30d',(select count(*) from public.hq_marketing_events where occurred_at>=now()-interval '30 days' and event_type in ('lead_created','signup')),'conversions_30d',(select count(*) from public.hq_marketing_events where occurred_at>=now()-interval '30 days' and event_type in ('subscription_started','paid_conversion'))); end; $$;
revoke all on function public.hq_marketing_overview() from public,anon; grant execute on function public.hq_marketing_overview() to authenticated;
commit;
